	} else if preview != nil && len(preview.FilesToDelete) > 0 {
		fmt.Fprintf(errW, "\nWarning: The following untracked files will be DELETED:\n")
		for _, f := range preview.FilesToDelete {
			fmt.Fprintf(errW, "  - %s\n", f)
		}
		fmt.Fprintf(errW, "\n")
	}
}

